INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein Remote-Desktop-System immer eine lokale Installation von Anwendungen benötigt?', 2, '[{"text": "Nein", "correct": true, "because": "Anwendungen laufen zentral auf dem Server"}, {"text": "Ja", "correct": false, "because": "Client greift nur auf Server zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutze ich primär für eine sichere Verbindung zu einem Remote-Desktop?', 3, '[{"text": "RDP", "correct": true, "because": "Standardprotokoll für Remote Desktop"}, {"text": "FTP", "correct": false, "because": "Für Dateiübertragung"}, {"text": "HTTP", "correct": false, "because": "Für Webzugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für eine zentrale Desktop-Bereitstellung entscheidend?', 5, '[{"text": "RD Session Host", "correct": true, "because": "Bereitstellung von Sitzungen"}, {"text": "RD Gateway", "correct": true, "because": "Sicherer Externzugriff"}, {"text": "Lokaler Grafiktreiber", "correct": false, "because": "Nicht zentral relevant"}, {"text": "Hohe Client-CPU", "correct": false, "because": "Server übernimmt Last"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein RD Gateway erhöht die Sicherheit. b) Es ersetzt den Session Host.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Gateway ergänzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung einer Remote-Desktop-Umgebung?', 4, '[{"text": "Netzwerklatenz", "correct": false, "because": "Kritisch für Performance"}, {"text": "Benutzerberechtigungen", "correct": false, "because": "Wichtig für Zugriff"}, {"text": "Client-Bildschirmfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Remote-Desktop ohne Internet funktioniert?', 2, '[{"text": "Ja", "correct": true, "because": "Lokales Netzwerk ausreichend"}, {"text": "Nein", "correct": false, "because": "Internet nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle verbessert den Zugriff für externe Benutzer?', 4, '[{"text": "RD Gateway", "correct": true, "because": "Sichert und steuert Externzugriff"}, {"text": "RD Web Access", "correct": false, "because": "Bietet nur Weboberfläche"}, {"text": "RD Licensing", "correct": false, "because": "Verwaltet Lizenzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Remote-Desktop-Systeme immer teuer sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kosteneffizient durch Zentralisierung"}, {"text": "Ja", "correct": false, "because": "Kosten abhängig von Umfang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht jede Sitzung eine eigene Lizenz?', 2, '[{"text": "Ja", "correct": true, "because": "Pro Benutzer oder Gerät nötig"}, {"text": "Nein", "correct": false, "because": "Lizenzierung ist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern eine Remote-Desktop-Umgebung ab?', 5, '[{"text": "Zwei-Faktor-Authentifizierung", "correct": true, "because": "Erhöht Zugriffssicherheit"}, {"text": "VPN-Verbindung", "correct": true, "because": "Schützt Datenübertragung"}, {"text": "Hohe Bildschirmauflösung", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Lokale Festplatte", "correct": false, "because": "Nicht zentral relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Skalierung eines Remote-Desktop-Systems?', 4, '[{"text": "Serverkapazität", "correct": true, "because": "Bewältigt mehr Sitzungen"}, {"text": "Client-Speicher", "correct": false, "because": "Server übernimmt Last"}, {"text": "Farbtiefe", "correct": false, "because": "Irrelevant für Skalierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) RD Web Access bietet browserbasierten Zugriff. b) Es ersetzt den RD Gateway.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Gateway für Sicherheit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Remote-Desktop-Bereitstellung?', 3, '[{"text": "RD Session Host", "correct": false, "because": "Kern für Sitzungen"}, {"text": "Netzwerkverbindung", "correct": false, "because": "Notwendig für Zugriff"}, {"text": "Lokale GPU", "correct": true, "because": "Server übernimmt Rendering"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich eine Verbindung zu einem Remote-Desktop herstelle?', 4, '[{"text": "RDP-Client mit Serveradresse", "correct": true, "because": "Direkter Zugriff auf Sitzung"}, {"text": "FTP-Client", "correct": false, "because": "Für Dateiübertragung"}, {"text": "Browser ohne Web Access", "correct": false, "because": "Nur mit RD Web Access"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Remote-Desktop ohne Firewall sicher ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Firewall schützt vor Angriffen"}, {"text": "Ja", "correct": false, "because": "Sicherheit zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature verbessert die Performance bei vielen Nutzern?', 3, '[{"text": "Load Balancing", "correct": true, "because": "Verteilt Sitzungen gleichmäßig"}, {"text": "Hohe Client-RAM", "correct": false, "because": "Serverlast entscheidend"}, {"text": "Lokale Software", "correct": false, "because": "Zentral bereitgestellt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein RD Connection Broker nur für Lizenzen da?', 3, '[{"text": "Nein", "correct": true, "because": "Verwaltet Sitzungen und Verbindungen"}, {"text": "Ja", "correct": false, "because": "Mehr als nur Lizenzierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen eine Remote-Desktop-Lösung benutzerfreundlich?', 5, '[{"text": "Schnelle Verbindungszeit", "correct": true, "because": "Reduziert Wartezeit"}, {"text": "Einfache Authentifizierung", "correct": true, "because": "Vereinfacht Zugriff"}, {"text": "Komplexe Passwörter", "correct": false, "because": "Kann Benutzer frustrieren"}, {"text": "Lokale Installationen", "correct": false, "because": "Zentraler Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Remote-Desktop-Umgebung unwichtig?', 3, '[{"text": "Serverleistung", "correct": false, "because": "Entscheidend für Nutzer"}, {"text": "Sicherheitsrichtlinien", "correct": false, "because": "Schützen Daten"}, {"text": "Client-Tastaturlayout", "correct": true, "because": "Kein zentraler Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was tue ich, wenn ein Benutzer keinen Zugriff auf eine Sitzung hat?', 4, '[{"text": "Berechtigungen prüfen", "correct": true, "because": "Fehlende Rechte häufige Ursache"}, {"text": "Client neu formatieren", "correct": false, "because": "Zu aufwendig"}, {"text": "Server abschalten", "correct": false, "because": "Beeinträchtigt alle Nutzer"}]');
